Contract CoCoMEOrderProducts::orderItem(barcode:Integer,quantity:Integer): Boolean {
          definition:
          obs:Set(Item) = Item.allInstance()->select(o | o.Barcode = barcode)

            precondition:
          barcode > 0 and quantity > 0

            postcondition:
          let foundItem:Item = obs->any(i | true) in let addOb:OrderEntry in addOb.oclIsNew() and addOb.Item = foundItem and addOb.Quantity = quantity and addOb.SubAmount = foundItem.Price * quantity and CurrentOrderProduct.ContainedEntries->including(addOb)

        }
